<?php
declare(strict_types=1);
namespace Liberu\RealEstate\ListingsFilament\Resources;
use Filament\Actions\DeleteAction; use Filament\Actions\EditAction; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder; use Liberu\RealEstate\Listings\Models\Listing; use Liberu\RealEstate\ListingsFilament\Resources\ListingResource\Pages\CreateListing; use Liberu\RealEstate\ListingsFilament\Resources\ListingResource\Pages\EditListing; use Liberu\RealEstate\ListingsFilament\Resources\ListingResource\Pages\ListListings;
final class ListingResource extends Resource { protected static ?string $model=Listing::class; protected static string|\BackedEnum|null $navigationIcon='heroicon-o-megaphone'; protected static string|\UnitEnum|null $navigationGroup='Real Estate'; public static function form(Schema $schema):Schema{return $schema->components([TextInput::make('title')->required()->maxLength(255),Select::make('status')->options(['draft'=>'Draft','ready'=>'Ready','published'=>'Published','suspended'=>'Suspended','withdrawn'=>'Withdrawn'])->required(),TextInput::make('price')->numeric()->minValue(0),TextInput::make('available_from')->date()]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('title')->searchable(),TextColumn::make('status')->badge(),TextColumn::make('price')->money('GBP'),TextColumn::make('created_at')->dateTime()->sortable()])->recordActions([EditAction::make(),DeleteAction::make()])->defaultSort('created_at','desc');} public static function getEloquentQuery():Builder{$teamId=auth()->user()?->current_team_id;return parent::getEloquentQuery()->when($teamId===null,fn(Builder $query):Builder=>$query->whereRaw('1 = 0'),fn(Builder $query):Builder=>$query->forTeam($teamId));} public static function getPages():array{return ['index'=>ListListings::route('/'),'create'=>CreateListing::route('/create'),'edit'=>EditListing::route('/{record}/edit')];} }
